class GenericSwUpdate(GenericBts):
    """Base keywords software updates"""

    YAFT_SVN_REPO = 'https://svne1.access.nsn.com/isource/svnroot/BTS_T_YAFT/trunk/'
    SVN_LOGIN = SVN_LOGIN
    SVN_PASS = SVN_PASSWORD

    supported_bts_types = 'GNB', 'ENB'

    def __init__(self, bts_type, comm):
        """
        Constructor of SwUpdate class.
        :param bts_type: GNB|ENB
        :param comm: Object of EnbCommissioning or GnbCommissioning class
        :return: None
        """
        if bts_type not in self.supported_bts_types:
            raise ValueError('{} is not a supported bts type'.format(bts_type))
        super(GenericSwUpdate, self).__init__(bts_type=bts_type)
        self.comm = comm

    @login_logout
    def update_software(self, sw_package_dir, timeout=600, bts_id=0, du_id=0, should_reset_radios=False,
                        override_ru_software=None, independent_sw_update_type=None):
        """
        Updates bts software with given sw package
        :param timeout: timeout given in seconds for sw update operation
        :param sw_package_dir: directory with software package
        :param bts_id:  int
        :param du_id: int
        :param boolean should_reset_radios: Activate reset radios flag.
        :param boolean override_ru_software: Optional, default: false
        :param string independent_sw_update_type: Optional, ["RuSwOnly"|"All"]

        :return:
        """
        self.admin.update_software(sw_package_dir, timeout=int(timeout),
                                   connection=self.rest_alias.format(bts_id, du_id),
                                   should_reset_radios=should_reset_radios,
                                   override_ru_software=override_ru_software,
                                   independent_sw_update_type=independent_sw_update_type)

    @load_moler_configuration_from_tl()
    def update_software_via_yaft(self, sw_package_path, bts_id=0, du_id=0, yaft_dir='/home/ute/yaft_latest',
                                 ip='192.168.255.129', yaft_log_dir=None, additional_options=None):
        """
        Upload software via YAFT

        :param sw_package_path: path to software package
        :param bts_id:          BTS id - related to Test Line configuration.
        :param du_id:           DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :param yaft_dir:        directory path where YAFT script is located
        :param ip:              bts ip address
        :param yaft_log_dir:    location for YAFT logs - if not passed then OUTPUT_DIR used.
        :param additional_options:    additional YAFT options

        :return:
        """

        if not yaft_log_dir:
            now = datetime.datetime.now().strftime("%Y%m%d-%H%M%S")
            yaft_log_dir = os.path.join(get_builtin_value('OUTPUT_DIR'), 'yaft', now)

        bts_ws = DeviceFactory.get_device(name=self.ws_du_alias.format(bts_id, du_id))
        bts_ws.goto_state("UNIX_REMOTE")
        bts_ws.get_cmd(cmd_name="cd", cmd_params={'path': yaft_dir})()
        bts_ws.get_cmd(cmd_name="mkdir", cmd_params={'path': yaft_log_dir, 'options': '-p'})()

        bts_ws.get_cmd(cmd_name="run_script", cmd_params={'script_command': 'pip3 install --upgrade pip'})(timeout=120)
        bts_ws.get_cmd(cmd_name="run_script", cmd_params={'script_command': 'pip3 install -U paramiko'})(timeout=120)
        yaft_command = "python3 yaft.py -i {} -z {} -l {} -K --ask_for_password --ignore_FSPs".format(
            ip, sw_package_path, yaft_log_dir
        )
        if additional_options:
            yaft_command = "{} {}".format(yaft_command, additional_options)
        password_event = bts_ws.get_event(
            event_name='wait4',
            event_params={'detect_patterns': [re.compile("Password:")]}
        )
        password_event.add_event_occurred_callback(
            callback=self._password_callback,
            callback_params={'bts_id': bts_id, 'du_id': du_id, 'password': 'oZPS0POrRieRtu'}
        )
        password_event.start()
        yaft_cmd = bts_ws.get_cmd(cmd_name="run_script",
                                  cmd_params={
                                      'script_command': yaft_command,
                                      'success_regex': [re.compile('Flashing done')],
                                      'error_regex': re.compile("(?!urlopen )error(?! timed out)",
                                                                re.IGNORECASE)})
        yaft_cmd(timeout=600)
        password_event.cancel()

    def _password_callback(self, bts_id=0, du_id=0, password='oZPS0POrRieRtu'):
        bts_ws = DeviceFactory.get_device(name=self.ws_du_alias.format(bts_id, du_id))
        time.sleep(1)
        bts_ws.io_connection.moler_connection.send("{}{}".format(password, "\n"))

    @load_moler_configuration_from_tl()
    def download_yaft(self, bts_id=0, du_id=0, download_dir='/home/ute/yaft_latest'):
        """
        Download YAFT lib from svn
        :param bts_id:          BTS id - related to Test Line configuration.
        :param du_id:           DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :param download_dir:    path to directory where YAFT will be downloaded
        :return:
        """
        bts_ws = DeviceFactory.get_device(name=self.ws_du_alias.format(bts_id, du_id))
        bts_ws.goto_state("UNIX_REMOTE")
        bts_ws.get_cmd(cmd_name="mkdir", cmd_params={'path': download_dir, 'options': '-p'})()
        bts_ws.get_cmd(cmd_name="rm", cmd_params={'file': os.path.join(download_dir, '*'), 'options': '-rf'})()
        download_cmd = "svn checkout --non-interactive --trust-server-cert --username {} --password {} {} {}".format(
            self.SVN_LOGIN, self.SVN_PASS, self.YAFT_SVN_REPO, download_dir)
        # Checked out revision 1096.
        download_yaft = bts_ws.get_cmd(cmd_name="run_script",
                                       cmd_params={
                                           'script_command': download_cmd,
                                           'success_regex': [re.compile(r'Checked out revision \d+.')]})
        download_yaft(timeout=60)

    def copy_sw_build_from_local_unix_to_ws(self, sw_package_path, destination_dir='/tmp/builds/', timeout=5 * 60,
                                            bts_id=0, du_id=0):
        """
        SCP sw build from local Unix to BTS WorkStation.

        :param sw_package_path: path to software package
        :param destination_dir: path dir on the BTS WorkStation
        :param timeout:         timeout for the operation.
        :param bts_id:          BTS id - related to Test Line configuration.
        :param du_id:           DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :return: path to sw build on remote workstation
        """
        upload_files_between_devices(local_dir=os.path.dirname(sw_package_path),
                                     local_file=os.path.basename(sw_package_path),
                                     remote_device_name=self.ws_du_alias.format(bts_id, du_id),
                                     remote_dir=destination_dir,
                                     timeout=timeout
                                     )
        return os.path.join(destination_dir, os.path.basename(sw_package_path))

    def download_sw_package(self, sw_version, target_dir, by_nominal=False):
        """
        Downloads given software package to target_dir
        :param sw_version: software version in str format, eg: 'SBTS00_ENB_9999_210318_000011'
        :param target_dir: directory to which build should be downloaded: str
        :param by_nominal: if set to True sw_version is treated like in nominal form eg: nominal: 5G21A_11.800.1213
                           raw_sw_string: 5G21A_GNB_0011_000800_001213
        :return: path to software package
        """
        subprocess.Popen(["mkdir", "-p", target_dir], stdout=subprocess.PIPE, stderr=subprocess.PIPE).communicate()

        version_creator = SwVersionFactory.create_sw_version_from_nominal if by_nominal else \
            SwVersionFactory.create_sw_version
        sw_version = version_creator(sw_version)
        sw_package_file_path = os.path.join(target_dir, sw_version.get_package())
        need_to_download = True
        if sw_version.get_package() in os.listdir(target_dir):
            logging.debug(f"Software package {sw_package_file_path} already exists")
            if self._is_file_being_downloaded(sw_version.url):
                logging.debug(f"Software package {sw_package_file_path} is being downloaded - "
                              f"waiting for it to finish")
                self._wait_for_file_download(sw_version.url)

            if self._test_zip_file(sw_package_file_path):
                logging.info(f'Software package {sw_package_file_path} tested and file is correct')
                need_to_download = False
            else:
                logging.info(f'Software package {sw_package_file_path} is corrupted - '
                             f'will be downloaded again')
                os.remove(sw_package_file_path)
        if need_to_download:
            self.download_from_arti(url=sw_version.url,
                                    local_sw_file_path=sw_package_file_path,
                                    api_key=sw_version.api_key)

        return sw_package_file_path

    @staticmethod
    def download_from_arti(url, local_sw_file_path, api_key):
        """
        Downloads a software package from an Artifactory repository to the specified path.
        :param url: The URL of the software package to download.
        :param local_sw_file_path: The local file path where the downloaded package will be saved.
        :param api_key: The API key used for authentication with the Artifactory repository.
        :raises Exception: If the download fails or the server returns a non-200 status code.
        :raises requests.exceptions.Timeout: If the download operation times out.
        """
        headers = {'X-JFrog-Art-Api': api_key}
        try:
            sw_data = requests.get(url, headers=headers, stream=True, timeout=60)
            if sw_data.status_code == 200:
                with open(local_sw_file_path, 'wb') as sw_file:
                    for chunk in sw_data.iter_content(chunk_size=1024):
                        sw_file.write(chunk)
                        sw_file.flush()
                logging.info(f'Software package downloaded successfully: {local_sw_file_path}')
            else:
                raise Exception(f'Software package has not been downloaded.\n STATUS_CODE: {sw_data.status_code}\n '
                                f'RESPONSE: {sw_data.text}')
        except requests.exceptions.Timeout as err:
            raise Exception(f'Software package download timed out : {err}')

    @staticmethod
    def _test_zip_file(file_path):
        try:
            with zipfile.ZipFile(file_path, 'r') as zip_ref:
                zip_ref.testzip()
            return True
        except zipfile.BadZipFile:
            return False

    @staticmethod
    def _is_file_being_downloaded(url_cmd):
        for proc in psutil.process_iter(['pid', 'name', 'cmdline']):
            cmdline = proc.info.get('cmdline')
            if cmdline and url_cmd in cmdline:
                return True
        return False

    def _wait_for_file_download(self, url_cmd, timeout=1800, check_interval=10):
        """
        Wait for the file to finish downloading.
        :param file_path: path to the file being downloaded
        :param timeout: maximum time to wait for the file to finish downloading
        :param check_interval: time interval between checks (in seconds)
        :return: True if the file is fully downloaded, False if the timeout is reached
        """
        start_time = time.monotonic()

        while time.monotonic() - start_time < timeout:
            if not self._is_file_being_downloaded(url_cmd):
                logging.info(f"File '{url_cmd}' has been fully downloaded.")
                return True
            logging.debug(f"File is still being downloaded, waiting {check_interval} seconds and check again")
            time.sleep(check_interval)

        logging.warning(f"Timeout reached while waiting for file '{url_cmd}' to finish downloading.")
        return False

    def reset_configuration(self, bts_id=0, du_id=0):
        """
        Perform configuration reset
        :return:
        """
        self.comm.reset_configuration(bts_id=bts_id, du_id=du_id)

    @login_logout
    def wait_sw_update_possible(self, readiness_timeout, bts_id=0, du_id=0):
        """
        Wait until sw update is possible.
        :param readiness_timeout: timeout for the bts to be ready in seconds
        :param bts_id:  BTS id - related to Test Line configuration.
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :return:
        """
        self.admin.wait_sw_update_possible(readiness_timeout=readiness_timeout,
                                           timeout=(readiness_timeout + 100),
                                           connection=self.rest_alias.format(bts_id, du_id))

    def download_multiple_builds(self, builds, output_path):
        """
        Download multiple SW packages to output path
        :param builds: array with software version in str format, eg: 'SBTS00_ENB_9999_210318_000011'
        :param output_path: directory to which build should be downloaded: str
        :return: array with paths to SW
        """
        downloaded_builds = []
        if not os.path.exists(output_path):
            os.makedirs(output_path)
        for build in builds:
            downloaded_builds.append(self.download_sw_package(sw_version=build, target_dir=output_path))
        return downloaded_builds


@six.add_metaclass(Singleton)
class EnbSwUpdate(GenericSwUpdate):
    """Class contains SCF keywords for eNB"""

    bts_type = 'ENB'

    def __init__(self):
        """
        Constructor of Enb class.

        """
        super(EnbSwUpdate, self).__init__(bts_type=EnbSwUpdate.bts_type, comm=EnbCommissioning())


@six.add_metaclass(Singleton)
class GnbSwUpdate(GenericSwUpdate):
    """Class contains SCF keywords for gNB"""

    bts_type = 'GNB'

    def __init__(self):
        """
        Constructor of Gnb class.

        """
        super(GnbSwUpdate, self).__init__(bts_type=GnbSwUpdate.bts_type, comm=GnbCommissioning())
